import{_ as o,o as a,c as t,a2 as _}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 1) - OSD: Locally Repairable Codes","description":"","frontmatter":{"title":"CDS G/H (Day 1) - OSD: Locally Repairable Codes","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["Ceph","分布式存储","本地可修复代码","Erasure Code","数据恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_OSD_-_Locally_Repairable_Codes.md","filePath":"posts/2014/CDS_G_H_Day_1_-_OSD_-_Locally_Repairable_Codes.md","lastUpdated":1780459816000}'),l={name:"posts/2014/CDS_G_H_Day_1_-_OSD_-_Locally_Repairable_Codes.md"};function r(s,e,i,n,p,d){return a(),t("div",null,[...e[0]||(e[0]=[_("<p>本次会议主要讨论了Ceph中本地可修复代码（Locally Repairable Codes，LRC）的提案和实现方案。</p><p><strong>会议要点</strong>：</p><ul><li><strong>本地可修复代码介绍</strong>： LRC通过编码技术将数据块编码成多个数据块和校验块，实现数据块在本地机架内的修复，避免跨机架的数据传输，节省带宽。</li><li><strong>数据块重映射</strong>： 为了实现LRC，需要将数据块映射到特定的OSD上。L提出了将数据块映射委托给Erasure Code插件的想法，以便更灵活地控制数据块的存储位置。</li><li><strong>语法和配置</strong>： 在RCode配置文件中添加新的键“layers”，用于指定要使用的Erasure Code插件。</li><li><strong>解码过程</strong>： 讨论了在解码过程中如何选择合适的编码层进行修复，以及如何处理不同数量的数据块丢失情况。</li><li><strong>本地修复</strong>： 讨论了本地修复的实现方式，以及如何避免跨数据中心的数据传输。</li><li><strong>编码算法</strong>： 讨论了是否可以在不同层使用不同的编码算法，以及如何处理一些特定的编码方案。</li><li><strong>其他讨论</strong>： 讨论了Facebook和Azure等公司提出的本地可修复代码方案，以及如何将这些方案融入到Ceph中。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>L将继续完善本地可修复代码的提案，并与其他研发人员讨论和改进。</li><li>Sam和Andrea将协助L进行相关工作。</li><li>其他研发人员将根据讨论结果提供反馈和建议。</li></ul><p><strong>关键词</strong>： 本地可修复代码（LRC），Erasure Code，数据块重映射，RSet步骤，解码，本地修复，编码算法</p>",6)])])}const c=o(l,[["render",r]]);export{g as __pageData,c as default};
